/*
 * MOVING BLOCKS IN THE CHAIN EDITOR WITHOUT CUTTING THE ROW, AND MENDING A
 * ROW THAT IS ALREADY CUT. One plan for both ends: the phone's chain editor
 * (mobile/src/screens/Edit.js, its copy of this file generated by
 * `npm run sync:rules`) and the browser's and computer window's
 * (src/components/GridEditor.jsx), so the two cannot disagree.
 *
 * "Editing the chain, moving compressor after the NAM block caused the sound
 * to stop completely" (Justin, 16 November 2026, his Axe-Fx III through his
 * Raspberry Pi, computer app 1.90.63).
 *
 * WHAT WENT WRONG. A drag in the chain editor deals the lane's blocks back
 * into the same columns in their new order (shared/lane-order.mjs): every
 * moved cell is emptied, then each block is put back in its new cell. On a
 * gen-3 unit (FM3, FM9, Axe-Fx III) a join between two cells lives in the
 * cell it FEEDS, as the rows of the column before that feed it, and the drag
 * sent no join at all and checked only where the blocks had gone. His log
 * says "landed" four times over a row that then made no sound, twice, and he
 * saved it so twice (preset 390). The most likely state is that the row read
 * "fed from nothing" from column 2 on: a block put into a cell joins nothing
 * on his unit (his 15 November build), and the clear or the put took the
 * cell's join with it. WHICH OF THOSE IT IS IS NOT KNOWN: the unit may drop a
 * cell's join when the cell is emptied, when it is selected, when a block is
 * put in it, or the join of the cell after it too. This plan works for all of
 * them, and the log lines it writes settle which.
 *
 * WHAT A MOVE DOES NOW (`planMove`, then `runMove`):
 *
 *   1. The grid is read before anything is written (GET /preset/grid, which
 *      carries every cell's feeds AND the bare wires, the shunts; the chain
 *      read leaves shunts out). The joins INTO each moved column and OUT of
 *      it into the next column are taken from that read, as one set with no
 *      join twice.
 *   2. A move whose joins the app could not make again is refused BEFORE
 *      anything is cleared, in words: out of a six-row unit's top row from
 *      an even column (lib/gen3-grid `cableKnown`), and, through a computer
 *      app older than 1.90.82 on a six-row unit, any join that computer
 *      would send to the wrong cell (lib/gen3-grid `cableAsTheLaw`). A join
 *      along row 3 or 4 is the same bytes either way, so his drag on row 3
 *      goes through his Pi; a move whose blocks also join another row may
 *      be refused through it.
 *   3. The cells are cleared and the blocks put back as before (no other way
 *      to move a block has been seen on a unit), the grid is read again, and
 *      the row is WRITTEN TO THE LOG BEFORE ANYTHING IS REPAIRED, so his next
 *      log says whether the unit keeps a join through a clear.
 *   4. Only the joins that are now missing are sent, the grid is read again,
 *      and every join is checked against the read before. Where one is still
 *      missing the screen says so where the move was made, with "Join the
 *      row" (`joinRow`), which sends what is missing and reads again. The
 *      row is then asked on that last read as a cut row is (`rowCuts`, empty
 *      spaces counted), so a cut the plan did not cover (a block brought in
 *      from after the Output, whose column nothing fed) is said too; and a
 *      moved block the unit did not put in its new cell is named, with no
 *      button, since nothing can be joined into an empty cell: as a space
 *      with no sound past it only between the row's Input and Output, and
 *      past the Output or before the Input as a block no longer in the
 *      preset (`notPlacedWords`).
 *   5. A move that fails part-way puts the blocks back where they were and
 *      gets the same rejoin; the read after says which blocks are not back,
 *      and the words never claim they are (`putBackSaid`).
 *   6. Never a join out of an Output or into an Input: the joins belong to
 *      the columns, and an Input or Output dragged along the row (or past by
 *      another block) would otherwise be joined where Fractal's own editors
 *      never put a cable.
 *   7. EVERY WRITE IS HELD TO THE PRESET THE MOVE WAS MADE ON (`onPreset`,
 *      Quick build's rig unitOnPreset at both ends), where the app makes the
 *      joins and the screen can name the preset (the screens hand no
 *      `onPreset` otherwise): a footswitch that changes preset mid-move stops
 *      it there, and nothing more, a join least of all, goes into the other
 *      preset. The first clear goes on the ask made just before it, unless
 *      settings were read in between (`measure`): then it is asked again,
 *      and a unit on another preset then, or not saying, gets nothing and
 *      is said as a move refused before anything was sent.
 *
 * MENDING WHAT IS ALREADY CUT (`rowCuts`): a block on the row of an Input,
 * between it and that row's Output, that is fed from NOTHING (so no parallel
 * path feeds it either) is where the row is cut. The chain editor offers
 * "Join the row" for it: a join into each such cell from the cell before it
 * on the same row, where that cell holds a block, a bare wire or the Input.
 * Only where the app can make EVERY join the cut needs: one it cannot (the
 * top row's, an old computer app's, or one with an empty cell before it) is
 * said with its reason and no button, as a drag that needs one is refused.
 * Never on a row with cells fed from another row (a parallel path), never on
 * a unit with no joins to make (an AM4, a VP4, an Axe-Fx II), and never over
 * Bluetooth, where the chain editor is not. After it, the row is asked again
 * (rowCuts on the read joinRow makes, ALWAYS with empty spaces counted), and
 * only a row that reads whole, with no empty space between its Input and
 * Output, is called joined again.
 *
 * SETTINGS ARE MEASURED, NEVER WRITTEN BACK, AND ON HIS ACCOUNT ONLY
 * (`measure`). Before and after a move each moved block is read once
 * (`settingsSaid`): a NAM block's capture slot and one knob of every block go
 * in the log, and nothing on the screen says whether they were kept. Two
 * reads a block is a slower drag, so a customer's is not measured. A saved
 * preset keeps only the blocks in its grid, so a block taken out and put
 * back may come back at its defaults; his next log says.
 *
 * COORDINATES are the display ones (rows and columns from nought), as
 * shared/split-chain.mjs. A JOIN is { srcRow, srcCol, destRow }: cell
 * (destRow, srcCol + 1) fed from row srcRow of the column before.
 *
 * This file writes nothing itself: `runMove` and `joinRow` are handed a wire
 * ({ gridCells, clearCell, placeBlock, setCable, readBlock }) by each end,
 * and `onPreset` to hold each write to the preset.
 */
import { colLabel, rowLabel } from './grid-plan.mjs'
import { isOlder } from './versions.mjs'

/* ---------------------------------------------------------------- */
/* Which joins the app can make                                      */
/* ---------------------------------------------------------------- */

/** The computer app release that builds a six-row join the right way at every row (ForgeFX gridCable.ts). */
export const CABLES_RIGHT_FROM = '1.90.82'

/** Whether a computer app of this version builds six-row joins by the codec's old law: older than 1.90.82, or not saying which it is. */
export const oldCableBytes = (version) => isOlder(version, CABLES_RIGHT_FROM) !== false

/**
 * Whether the unit's joins are the app's to make here at all: a grid unit
 * whose driver lays cables (the FM3, FM9 and Axe-Fx III say `gridRouting`;
 * the demo's grid units are grids and say nothing). Never a linear unit (an
 * AM4 or a VP4, whose slots have no joins), and never an Axe-Fx II, whose
 * driver lays none (`gridRouting: false`).
 */
export function cablesLaid(caps) {
  if (!caps || typeof caps !== 'object' || caps.slotModel === 'linear') return false
  if (caps.gridRouting === false) return false
  return caps.gridRouting === true || caps.slotModel === 'grid'
}

/**
 * A join out of (srcRow, srcCol), counted from nought, that the app can build:
 * on a six-row grid never out of the TOP row from an even column as the unit
 * counts them (an odd one here). lib/gen3-grid `cableKnown`, in display
 * coordinates; a test holds the two to each other over every cell.
 */
export const joinMakeable = (rows, srcRow, srcCol) => !(rows === 6 && srcRow === 0 && srcCol % 2 === 1)

/**
 * Whether a computer app older than 1.90.82 sends this join to the cells asked
 * for: on four rows always; on six, into row 3 or 4, or out of an odd column
 * as the unit counts them (an even one here) into row 1, 5 or 6. lib/gen3-grid
 * `cableAsTheLaw`, in display coordinates; a test holds the two together.
 */
export const joinAsTheLaw = (rows, srcCol, destRow) =>
  rows !== 6 || destRow === 2 || destRow === 3 || (srcCol % 2 === 0 && (destRow === 0 || destRow === 4 || destRow === 5))

/**
 * Whether a browser page's joins are built by a computer app OTHER than the
 * one that served the page, so its version decides the bytes: through the
 * relay (`remote`), or the hosted website open on the computer that runs the
 * app (`mac`, not served by it). The computer's own window and its Wi-Fi page
 * (`served`) are this release, and build them right.
 */
export const builtElsewhere = ({ role, served = false } = {}) => role === 'remote' || (role === 'mac' && !served)

/** Where a join lands, in words: "row 3, column 2" (the cell it feeds). */
const joinedAt = (j) => `row ${rowLabel(j.destRow)} at column ${colLabel(j.srcCol + 1)}`

/** Why the app cannot make this join (in words a guitarist reads), or null when it can. `law` is a computer app sending the old bytes; `version` what it said it is. */
export function joinWhyNot(j, { rows = 4, law = false, version = null } = {}) {
  if (!joinMakeable(rows, j.srcRow, j.srcCol)) return `The app can’t join the top row out of column ${colLabel(j.srcCol)}.`
  if (law && !joinAsTheLaw(rows, j.srcCol, j.destRow)) {
    const which = version ? `The computer app on ${version}` : 'A computer app that doesn’t say its version'
    return `${which} sends the join into ${joinedAt(j)} to the wrong place. Update the computer app to 1.90.82 or later.`
  }
  return null
}

/* ---------------------------------------------------------------- */
/* Reading the grid                                                  */
/* ---------------------------------------------------------------- */

const cellAt = (cells, row, col) => (Array.isArray(cells) ? cells.find((c) => c && c.row === row && c.col === col) : null) || null
/** The rows a cell is fed from, as the read says them; null where the read did not say. */
const feeds = (cell) => (Array.isArray(cell?.fromRows) ? cell.fromRows.filter((r) => Number.isInteger(r)) : null)
const joinKey = (j) => `${j.srcRow}:${j.srcCol}>${j.destRow}`
const byColumn = (a, b) => a.srcCol - b.srcCol || a.srcRow - b.srcRow || a.destRow - b.destRow

/** Whether a fresh read shows this join: the cell it feeds is there and is fed from that row. */
export const joinedIn = (cells, j) => !!feeds(cellAt(cells, j.destRow, j.srcCol + 1))?.includes(j.srcRow)

/** The joins a fresh read does not show. */
export const missingJoins = (cells, joins) => (joins || []).filter((j) => !joinedIn(cells, j))

/** A join in words, for the log: "row 3 column 1 → column 2", or "→ row 4 column 2" across rows. */
export const joinSaid = (j) =>
  `row ${rowLabel(j.srcRow)} column ${colLabel(j.srcCol)} → ${j.destRow === j.srcRow ? '' : `row ${rowLabel(j.destRow)} `}column ${colLabel(j.srcCol + 1)}`

/**
 * A row as the unit read it, for the log: each cell from `first` to `last`
 * and which rows feed it, as Quick build's `rowAsRead` says it. `names`
 * (effect id → name) names a block the grid read calls by number.
 */
export function rowSaid(cells, row, first, last, names = null) {
  if (!Array.isArray(cells)) return 'not read'
  const parts = []
  for (let col = Math.max(0, first); col <= last; col++) {
    const cell = cellAt(cells, row, col)
    if (!cell) {
      parts.push(`column ${colLabel(col)} empty`)
      continue
    }
    const what = cell.isShunt ? 'a bare wire' : names?.get?.(cell.effectId) || cell.name || `block ${cell.effectId}`
    const rows = feeds(cell)
    const fed = rows === null ? 'feed not read' : rows.length ? `fed from row ${rows.map((r) => rowLabel(r)).join(' and ')}` : 'fed from nothing'
    parts.push(`column ${colLabel(col)} ${what}${col === 0 ? '' : ` (${fed})`}`)
  }
  return parts.join(', ')
}

const END_NAME = { input: /^input(\s*\d+)?$/i, output: /^output(\s*\d+)?$/i }
/* A gen-3 unit's own numbers for them (Input 1–5 and Output 1–4, lib/gen3Catalog), for a read that names neither. */
const END_IDS = { input: [37, 38, 39, 40, 41], output: [42, 43, 44, 45] }
/** Whether a cell is the Input (or the Output): the chain read's slug, else the grid read's own name, else the unit's number for it. */
function isEnd(cell, end, slugs = null) {
  if (!cell || cell.isShunt) return false
  const slug = slugs?.get?.(cell.effectId)
  if (slug) return slug === end
  return END_NAME[end].test(String(cell.name || '').trim()) || END_IDS[end].includes(cell.effectId)
}

/** The chain read's word for each block (effect id → slug), which says which block is an Input or an Output where the grid read cannot. */
const slugsOf = (blocks) => new Map((blocks || []).filter((b) => Number.isInteger(b?.effectId) && b.slug).map((b) => [b.effectId, b.slug]))

/** A row's Input and, after it on the same row, its Output, as a read has them: { input, output, onRow } (their columns, and the row's cells in order), or null. */
function rowEnds(cells, row, slugs) {
  const onRow = cells.filter((c) => c && c.row === row && Number.isInteger(c.col)).sort((a, b) => a.col - b.col)
  const input = onRow.find((c) => isEnd(c, 'input', slugs))
  const output = input ? onRow.find((c) => c.col > input.col && isEnd(c, 'output', slugs)) : null
  return input && output ? { input: input.col, output: output.col, onRow } : null
}

/** A read worth acting on: an answer with cells in it (an empty one after a move is a read that went wrong, not a grid with nothing in it). */
async function readCells(wire) {
  try {
    const cells = await wire.gridCells()
    return Array.isArray(cells) && cells.length ? cells : null
  } catch {
    return null
  }
}

/* ---------------------------------------------------------------- */
/* The words                                                         */
/* ---------------------------------------------------------------- */

export const JOIN_ROW = 'Join the row'
export const JOINING_ROW = 'Joining the row…'
export const NOT_READ_BEFORE = 'Nothing was moved: the unit didn’t answer when the app asked how the row is joined. Try again.'
export const CHAIN_CHANGED = 'Nothing was moved: the chain on the unit isn’t what’s on screen any more. It has been read again.'
export const WIRING_UNKNOWN = 'Nothing was moved: the computer app didn’t say how the row is joined, so the app couldn’t join it again after the move. Update the computer app, then try again.'

/** A move refused before anything was sent, because one of its joins could not be made again. */
export const refusedWords = (why) => `Nothing was moved: moving these blocks would cut the row, and the app couldn’t join it again. ${why}`

/** The first join still missing, where it is drawn: the lowest column, the lane's own row first. */
export function firstCut(still, row) {
  const list = [...(still || [])].sort(byColumn)
  return list.find((j) => j.destRow === row) || list[0] || null
}

/** After a move that left a join missing: "The blocks moved, but row 3 isn’t joined at column 2, so there’s no sound past it." */
export const cutAfterMove = (j) => `The blocks moved, but row ${rowLabel(j.destRow)} isn’t joined at column ${colLabel(j.srcCol + 1)}, so there’s no sound past it.`

/** After a move whose own joins all read back, but whose row the last read finds cut elsewhere (rowCuts' words, from "Row 3 …"). */
export const foundAfterMove = (cut) => `The blocks moved, but ${String(cut.text).charAt(0).toLowerCase()}${String(cut.text).slice(1)}`

/**
 * After a move the unit did not take whole: a moved block not in its new
 * cell, which reads empty ({ name, col, between, gone }, runMove's
 * `notPlaced`). "No sound past it" only of an empty cell BETWEEN the row's
 * Input and Output on the last read (`between`), where the sound does stop.
 * One past the Output, or before the Input, stops nothing: of that the words
 * say the block is not in the preset now, and only where that read has it
 * nowhere (`gone`); one the unit put somewhere else is the screens' own
 * check's to say. '' where there is nothing to say.
 */
export function notPlacedWords(row, list) {
  const at = (xs) => listed(xs.map((x) => `${x.name} at column ${colLabel(x.col)}`))
  const holes = (list || []).filter((x) => x.between === true)
  const lost = (list || []).filter((x) => x.between !== true && x.gone === true)
  const said = []
  if (holes.length) {
    const one = holes.length === 1
    said.push(`The unit didn’t take ${at(holes)}, so row ${rowLabel(row)} has ${one ? 'an empty space' : 'empty spaces'} there and no sound past ${one ? 'it' : 'them'}. Put a block in ${one ? 'it' : 'each'}, or move one back.`)
  }
  if (lost.length) {
    const one = lost.length === 1
    said.push(`The unit didn’t take ${at(lost)}, so ${one ? 'it isn’t' : 'they aren’t'} in this preset now. Add ${one ? 'it' : 'them'} again, or move one back.`)
  }
  return said.join(' ')
}

/** After a move whose rejoin could not be read back. */
export const uncheckedAfterMove = (row) => `The blocks moved, but the app couldn’t read row ${rowLabel(row)} back to check it’s joined.`

/** After a move that failed part-way and was put back. */
export const putBackCut = (j) => ` The blocks were put back, but row ${rowLabel(j.destRow)} isn’t joined at column ${colLabel(j.srcCol + 1)}, so there’s no sound past it.`

/** After a move that failed part-way and was put back, with no read to check the row by. */
export const uncheckedPutBack = (row) => `The blocks were put back, but the app couldn’t read row ${rowLabel(row)} back to check it’s joined.`

/** A row that reads cut, as the chain editor finds it on opening or after a read. */
export const cutRowWords = (row, col) => `Row ${rowLabel(row)} isn’t joined at column ${colLabel(col)}, so there’s no sound past it.`

/** A row left with an empty space between its Input and Output (a block moved out of it). */
export const holeWords = (row, col) =>
  `Row ${rowLabel(row)} has an empty space at column ${colLabel(col)} between its Input and Output, so the sound may stop there. Put a block in it, or move one back.`

/** A cut cell with nothing before it on the row: no join can be sent into it. */
export const emptyBeforeWords = (col) => `Column ${colLabel(col - 1)} is empty, so there’s nothing to join column ${colLabel(col)} from.`

/* The unit's own preset, asked before every write (`onPreset`). */
/** Before anything was sent: the move was not made. */
export const PRESET_MOVED_BEFORE = 'Nothing was moved: the unit is on another preset now.'
export const UNIT_QUIET_BEFORE = 'Nothing was moved: the unit didn’t say which preset it’s on. Try again.'
/** Part-way through a move. */
export const PRESET_MOVED_MID = 'The unit went to another preset during the move, so the app stopped and sent nothing more to it.'
export const UNIT_QUIET_MID = 'The unit stopped saying which preset it’s on during the move, so the app stopped there.'

const listed = (names) => (names.length < 2 ? names.join('') : `${names.slice(0, -1).join(', ')} and ${names[names.length - 1]}`)

/**
 * WHAT A MOVE THAT FAILED PART-WAY LEFT, in words that claim nothing the read
 * did not show. "Were put back" only where the read after has every block
 * taken out back in its own cell; a block that is not is named; with no read
 * to go by, the app says it tried. Null when there is nothing to add to the
 * failure's own words (a move with no joins of its own whose blocks all went
 * back without a throw).
 */
export function putBackSaid({ row, res }) {
  if (!res?.threw) return null
  const missing = Array.isArray(res.missingBack) ? res.missingBack : []
  const read = Array.isArray(res.after)
  const where = `row ${rowLabel(row)}`
  if (missing.length && read) return `The app tried to put the blocks back, but ${listed(missing)} ${missing.length === 1 ? 'isn’t' : 'aren’t'} back where ${missing.length === 1 ? 'it was' : 'they were'} in ${where}.`
  if (missing.length) return `The app tried to put the blocks back, but couldn’t put ${listed(missing)} back, and couldn’t read ${where} to check.`
  if (!read) return Array.isArray(res.plan?.joins) ? `The app tried to put the blocks back, but couldn’t read ${where} back to check them.` : null
  const cut = Array.isArray(res.plan?.joins) ? firstCut(res.still, row) : null
  return cut ? putBackCut(cut).trim() : null
}

/**
 * EVERYTHING A MOVE LEAVES SAID, for both screens: `issue` over the chain (or
 * null), `note` under the row ({ text, joins } with Join the row, or null),
 * and `line` for the browser's history.
 */
export function afterMoveSaid({ row, res }) {
  const joins = Array.isArray(res?.plan?.joins) ? res.plan.joins : null
  const r = rowLabel(row)
  if (res?.stopped === 'moved') return { issue: PRESET_MOVED_MID, note: null, line: `A move on row ${r} stopped: the unit went to another preset` }
  if (res?.threw) {
    const back = putBackSaid({ row, res })
    const failure = res.stopped === 'unknown' ? UNIT_QUIET_MID : res.threw.message
    const missing = Array.isArray(res.missingBack) ? res.missingBack : []
    const line = missing.length
      ? `A move on row ${r} failed; ${listed(missing)} ${missing.length === 1 ? 'wasn’t' : 'weren’t'} put back`
      : Array.isArray(res.after) || !joins
        ? `A move on row ${r} failed and its blocks were put back`
        : `A move on row ${r} failed and the app tried to put its blocks back`
    return { issue: back ? `${failure} ${back}` : failure, note: joins && back ? { text: back, joins } : null, line }
  }
  if (!joins) return { issue: null, note: null, line: null }
  if (res.stopped === 'unknown') return { issue: null, note: { text: `The blocks moved, but the unit stopped saying which preset it’s on, so the app didn’t join row ${r} again.`, joins }, line: null }
  if (!res.checked) return { issue: null, note: { text: uncheckedAfterMove(row), joins }, line: null }
  const notPlaced = Array.isArray(res.notPlaced) ? res.notPlaced : []
  /* A block the unit did not put in its new cell between the row's Input and Output: said by name, and no Join the row, which could only answer that the cell is empty. */
  if (notPlaced.some((x) => x.between === true)) return { issue: null, note: { text: notPlacedWords(row, notPlaced), joins: [] }, line: null }
  /* One it did not put past the Output, or before the Input, stops no sound: the row is said as its read has it, and the block that is gone after that. */
  const lost = notPlacedWords(row, notPlaced)
  const cut = firstCut(res.still, row)
  /* Every join the plan made reads back, and the row is still cut where the plan did not look (rowCuts on the same read). */
  const found = cut ? null : Array.isArray(res.cutsAfter) ? res.cutsAfter.find((c) => c.row === row) : null
  const note = cut ? { text: cutAfterMove(cut), joins } : found ? { text: foundAfterMove(found), joins: found.joins } : null
  if (!lost) return { issue: null, note, line: null }
  return { issue: null, note: note ? { text: `${note.text} ${lost}`, joins: note.joins } : { text: lost, joins: [] }, line: null }
}

/**
 * After "Join the row": joinRow's own answer. "Joined again" only where the
 * row was read after, every join asked for is there, and the row asked again
 * (rowCuts on that read, `cuts`) reads whole. Never "sent" of nothing sent.
 * `joins`, where given, is what the button is to send next ([] for none).
 */
export function joinedWords({ row, still, checked, readBefore = true, sent = 0, failed = null, stopped = null, skipped = [], cuts = null }) {
  const r = rowLabel(row)
  if (stopped === 'moved') return { ok: false, text: sent ? `The app stopped joining row ${r}: the unit went to another preset.` : 'No join was sent: the unit is on another preset now.', joins: [] }
  if (!readBefore) return { ok: false, text: `Nothing was sent: the unit didn’t answer when the app asked how row ${r} is joined. Try again.` }
  if (stopped === 'unknown') return { ok: false, text: `${sent ? `The app stopped joining row ${r}` : 'No join was sent'}: the unit didn’t say which preset it’s on. Try again.` }
  if (failed && !sent) return { ok: false, text: `Nothing was sent: ${failed}` }
  if (!checked) return { ok: false, text: `The app sent the joins, but couldn’t read row ${r} back to check them.` }
  const cut = firstCut(still, row)
  if (cut) {
    const at = `row ${rowLabel(cut.destRow)} at column ${colLabel(cut.srcCol + 1)}`
    if (!sent) {
      const empty = (skipped || []).find((j) => joinKey(j) === joinKey(cut))
      return { ok: false, text: `The app couldn’t join ${at}: ${empty ? `column ${colLabel(empty.empty)} is empty.` : 'nothing was sent.'}`, joins: empty ? [] : undefined }
    }
    if (failed) return { ok: false, text: `The app sent ${sent} join${sent === 1 ? '' : 's'}, then stopped: ${failed} Row ${rowLabel(cut.destRow)} still isn’t joined at column ${colLabel(cut.srcCol + 1)}.` }
    return { ok: false, text: `The app sent the joins, but row ${rowLabel(cut.destRow)} still isn’t joined at column ${colLabel(cut.srcCol + 1)}.` }
  }
  /* Only the pressed row's own: another row's cut and its joins are never drawn under this one. */
  const left = Array.isArray(cuts) ? cuts.find((c) => c.row === row) : null
  if (left) return { ok: false, text: left.text, joins: left.joins }
  return { ok: true, text: `Row ${r} is joined again.` }
}

/**
 * WHAT IS SAID UNDER A ROW, from what a write there left (`left`) and what
 * the last read of the grid found (`found`, rowCuts). A note about another
 * preset is not this one's (`preset`, the one on screen). An all-clear is
 * never drawn over a fresh read that finds the row cut; a refusal (a note
 * with nothing to send) keeps its words and takes the found cut's words and
 * Join the row under them; otherwise the write's own note stands.
 */
export function rowNote(left, found, preset = undefined) {
  const mine = left && (left.n === undefined || preset === undefined || left.n === preset) ? left : null
  if (!mine) return found || null
  if (!found) return mine
  if (mine.tone === 'ok') return found
  const sends = (x) => Array.isArray(x?.joins) && x.joins.length > 0
  if (!sends(mine) && sends(found)) return { ...found, text: `${mine.text} ${found.text}` }
  return mine
}

/* ---------------------------------------------------------------- */
/* The move                                                          */
/* ---------------------------------------------------------------- */

/**
 * THE PLAN FOR A DRAG, from the grid as read BEFORE anything is written.
 *
 * `moves` is lane-order's reorderPlan, each with the block's effect id
 * (`id`) and `name`: { id, name, from, to }, columns from nought on `row`.
 * `rows` and `cols` the unit's grid; `law` a computer app that sends the old
 * bytes, `version` what it said it is.
 *
 * Answers { ok: true, row, joins, moved, first, last, before } or
 * { ok: false, why } with the words to show; nothing is to be sent then.
 */
export function planMove({ cells, row, moves, rows = 4, cols = 12, law = false, version = null } = {}) {
  const list = (moves || []).filter((m) => m && Number.isInteger(m.from) && Number.isInteger(m.to) && Number.isInteger(m.id))
  if (!list.length) return { ok: false, why: null }
  if (!Array.isArray(cells) || !cells.length) return { ok: false, why: NOT_READ_BEFORE }
  /* Every block the lane says is moving is where the lane says it is, or the chain changed under the screen. */
  for (const m of list) {
    const here = cellAt(cells, row, m.from)
    if (!here || here.isShunt || here.effectId !== m.id) return { ok: false, why: CHAIN_CHANGED }
  }
  const moved = [...new Set(list.flatMap((m) => [m.from, m.to]))].sort((a, b) => a - b)
  const joins = []
  const seen = new Set()
  const add = (j) => {
    const k = joinKey(j)
    if (!seen.has(k)) {
      seen.add(k)
      joins.push(j)
    }
  }
  let known = true
  for (const col of moved) {
    /* INTO the moved column: every row of the column before that fed it. */
    if (col > 0) {
      const from = feeds(cellAt(cells, row, col))
      if (from === null) known = false
      else for (const r of from) if (cellAt(cells, r, col - 1)) add({ srcRow: r, srcCol: col - 1, destRow: row })
    }
    /* OUT of it: every cell of the next column it fed. */
    for (const next of cells) {
      if (!next || next.col !== col + 1) continue
      const from = feeds(next)
      if (from === null) known = false
      else if (from.includes(row)) add({ srcRow: row, srcCol: col, destRow: next.row })
    }
  }
  if (!known) return { ok: false, why: WIRING_UNKNOWN }
  /*
   * NEVER OUT OF AN OUTPUT OR INTO AN INPUT. A join belongs to its columns,
   * not its blocks, so a drag that moves an Output up the row (or a block
   * past it) would have the app send a cable out of the Output into the
   * block now after it, and one into an Input moved down. Fractal's editors
   * draw no such cable, none of the saved presets has one, and nothing has
   * ever sent one to a unit; neither carries sound the drag asked for. So
   * the plan leaves them out (and its check after never asks for them).
   */
  const dealt = new Map(list.map((m) => [m.to, { effectId: m.id, name: m.name }]))
  const holdsAfter = (r, c) => (r === row && dealt.has(c) ? dealt.get(c) : cellAt(cells, r, c))
  const carried = joins.filter((j) => !isEnd(holdsAfter(j.srcRow, j.srcCol), 'output') && !isEnd(holdsAfter(j.destRow, j.srcCol + 1), 'input'))
  joins.length = 0
  joins.push(...carried)
  joins.sort(byColumn)
  for (const j of joins) {
    const why = joinWhyNot(j, { rows, law, version })
    if (why) return { ok: false, why: refusedWords(why), join: j }
  }
  return { ok: true, row, joins, moved, first: Math.max(0, moved[0] - 1), last: Math.min(cols - 1, moved[moved.length - 1] + 1), before: cells }
}

/**
 * A move with no joins to keep: a linear unit (an AM4, whose slots have no
 * joins) or a grid whose driver lays none (an Axe-Fx II). Its blocks are
 * cleared and put back as they always were, and measured the same.
 */
export const plainMove = (row) => ({ ok: true, row, joins: null, moved: [], first: 0, last: 0, before: null })

/**
 * One block's settings in a few words, for the log: a NAM block's capture
 * (its slot, numbered from 001 as the unit shows it, and its name where the
 * read gives one), the model where the read names it, and the first knob.
 * `read` is the block's params read (blockParams), or null.
 */
export function settingsSaid(read) {
  if (!read || typeof read !== 'object') return 'not read'
  const parts = []
  if (read.capture && typeof read.capture === 'object') {
    const slot = read.capture.slot
    parts.push(Number.isInteger(slot) ? `capture ${String(slot + 1).padStart(3, '0')}${read.capture.name ? ` “${read.capture.name}”` : ''}` : 'capture not said')
  }
  const type = read.type && typeof read.type === 'object' ? read.type.name ?? read.type.value : read.type
  if (type !== null && type !== undefined && type !== '') parts.push(`model ${type}`)
  const knob = Array.isArray(read.named) ? read.named.find((p) => p && p.value !== undefined && p.value !== null) : null
  if (knob) parts.push(`${knob.name || `setting ${knob.id}`} ${typeof knob.value === 'number' ? Number(knob.value.toFixed(3)) : knob.value}`)
  return parts.length ? parts.join(', ') : 'nothing to say'
}

/**
 * WHICH PRESET THE UNIT IS ON, asked before a write (Quick build's rig
 * unitOnPreset, at both ends): `onPreset()` answers 'same', 'moved' or
 * 'unknown' (a throw, or anything else, is 'unknown'). Once it has said
 * 'moved' it is not asked again: nothing more goes to the unit's other
 * preset. With no `onPreset` (a unit whose joins are not the app's, or a
 * preset the screen cannot name) every write goes, as before.
 */
export function presetHold(onPreset) {
  let moved = false
  return async () => {
    if (typeof onPreset !== 'function') return 'same'
    if (moved) return 'moved'
    let on
    try {
      on = await onPreset()
    } catch {
      on = 'unknown'
    }
    if (on === 'moved') moved = true
    return on === 'same' || on === 'moved' ? on : 'unknown'
  }
}

/** Each moved block read once, in order, for the log; a failed read is said as not read. */
async function measure(moves, wire) {
  const out = new Map()
  if (typeof wire.readBlock !== 'function') return out
  for (const m of moves) {
    let said = 'not read'
    try {
      said = settingsSaid(await wire.readBlock(m.id))
    } catch {
      said = 'not read'
    }
    out.set(m.id, said)
  }
  return out
}

/**
 * Send the joins a read does not show, in order, stopping at the first the
 * link throws on (as runPlan does), and at the first the unit's preset
 * holds back (`hold`, presetHold). Never a join whose two cells are not
 * both there in that read: a join into or out of an empty cell is not the
 * app's to guess at, and is answered as `skipped`, with the empty column.
 */
async function sendMissing(joins, cells, wire, log, hold = async () => 'same') {
  const absent = missingJoins(cells, joins)
  const missing = []
  const skipped = []
  for (const j of absent) {
    const from = cellAt(cells, j.srcRow, j.srcCol)
    const into = cellAt(cells, j.destRow, j.srcCol + 1)
    if (from && into) missing.push(j)
    else skipped.push({ ...j, empty: into ? j.srcCol : j.srcCol + 1 })
  }
  let sent = 0
  let refused = 0
  let failed = null
  let stopped = null
  for (const j of missing) {
    const on = await hold()
    if (on !== 'same') {
      stopped = on
      log(`join ${joinSaid(j)}`, `not sent: ${on === 'moved' ? 'the unit is on another preset' : 'the unit didn’t say which preset it’s on'}`)
      break
    }
    try {
      const r = await wire.setCable(j.srcRow, j.srcCol, j.destRow, true)
      if (r && r.ok === false) refused += 1
      sent += 1
    } catch (err) {
      failed = err?.message || String(err)
      log(`join ${joinSaid(j)}`, `failed — ${failed}`)
      break
    }
  }
  return { absent, missing, skipped, sent, refused, failed, stopped }
}

const said = (r) => (r && r.ok === false ? 'refused' : r?.ok === true ? 'ok' : 'no answer')

/** A write held back because the unit is on another preset, or would not say: thrown, so the move stops where it is. */
const heldBack = (on) => Object.assign(new Error(on === 'moved' ? PRESET_MOVED_MID : UNIT_QUIET_MID), { held: on })

/**
 * Run a planned move against a unit: clear every moved cell, put every block
 * in its new one, read, log the row as the unit has it, send what is now
 * missing, read again, log it again.
 *
 * `wire` is { gridCells, clearCell, placeBlock, setCable, readBlock? };
 * `log(what, detail)` writes a `[chain]` line; `measure` reads each moved
 * block before and after, for the log (his account only, at both ends);
 * `hold` (presetHold) is asked before EVERY write, and `checkedFirst` says
 * it was asked just now, so the first clear goes without asking again,
 * unless settings are measured first: those reads are round trips, a
 * footswitch can land among them, and the first clear is asked then too.
 * `starting()` is called once, just before the first write is let go: never
 * for a move held back before it (the screens drop the Undo there, and the
 * phone marks the preset changed).
 * Never throws for the unit's sake: a write that throws (or is held back)
 * puts the cleared blocks back where they were, joins them again, and is
 * answered as `threw`. Held back because the unit is on ANOTHER preset, it
 * stops there and sends nothing more at all. Held back at the FIRST write,
 * before anything was sent, it is answered `heldBefore` ('moved' or
 * 'unknown') with no `threw`: the move was not made.
 *
 * Answers { threw, stopped, heldBefore, answers, refused, sent,
 * missingAfterMove, still, checked, after, missingBack, notPlaced }: `still`
 * the joins the last read does not show, `checked` whether there was a last
 * read to go by, `missingBack` the names of blocks taken out that are not
 * back in their own cells after a failure (by the last read, else the
 * put-backs that did not go), `notPlaced` the moved blocks ({ name, col,
 * between, gone }) whose new cell the last read shows empty after a move
 * that did not fail: `between` whether that cell is between the row's Input
 * and Output on that read (`blocks`, the chain read, names them where the
 * grid read cannot), `gone` whether the read has the block nowhere.
 */
export async function runMove({ plan, moves, wire, log = () => {}, names = null, measure: measuring = false, hold = presetHold(null), checkedFirst = false, starting = () => {}, blocks = null }) {
  const row = plan.row
  const joins = Array.isArray(plan.joins) ? plan.joins : null
  const line = (cells) => rowSaid(cells, row, plan.first, plan.last, names)
  if (joins) log(`move: row ${rowLabel(row)} before: ${line(plan.before)}`)
  const was = measuring ? await measure(moves, wire) : new Map()
  for (const m of moves) if (was.has(m.id)) log(`move: ${m.name} before: ${was.get(m.id)}`)

  const answers = []
  const cleared = []
  const notBack = []
  let threw = null
  let stopped = null
  /* The ask moveBlocks made counts for the first clear only if nothing went to the unit since: measuring did. */
  let fresh = checkedFirst && !measuring
  /* Whether anything has been let go to the unit yet: `starting` is called once, just before the first write, never for a move held back before it. */
  let begun = false
  const go = async () => {
    if (fresh) fresh = false
    else {
      const on = await hold()
      if (on !== 'same') throw heldBack(on)
    }
    if (!begun) {
      begun = true
      starting()
    }
  }
  try {
    for (const m of moves) {
      await go()
      cleared.push(m)
      const r = await wire.clearCell(row, m.from)
      answers.push(r)
      log(`clear ${m.name} from column ${colLabel(m.from)}`, said(r))
    }
    for (const m of moves) {
      await go()
      const r = await wire.placeBlock(row, m.to, m.id)
      answers.push(r)
      log(`place ${m.name} at column ${colLabel(m.to)}`, said(r))
    }
  } catch (err) {
    threw = err instanceof Error ? err : new Error(String(err))
    stopped = threw.held || null
  }
  const counted = () => ({ threw, stopped, answers, refused: answers.filter((r) => r && r.ok === false).length })

  /* HELD BACK BEFORE ANYTHING WAS SENT (the ask after his settings were read): the move was not made, and is answered so, never as one that failed part-way. */
  if (threw && stopped && !begun) {
    log(`move on row ${rowLabel(row)}`, `not sent: ${stopped === 'moved' ? 'the unit is on another preset' : 'the unit didn’t say which preset it’s on'}`)
    return { ...counted(), threw: null, heldBefore: stopped, joinsRefused: 0, sent: 0, missingAfterMove: null, still: [], checked: false, after: null, missingBack: [], notPlaced: [] }
  }
  if (threw && stopped === 'moved') {
    /* THE UNIT IS ON ANOTHER PRESET: nothing more goes to it, the blocks are not put back into it, and its grid is not read as this one's. */
    log(`move on row ${rowLabel(row)}`, `stopped: the unit is on another preset; ${cleared.length ? `${cleared.map((m) => m.name).join(', ')} had been taken out` : 'nothing had been sent'}`)
    return { ...counted(), joinsRefused: 0, sent: 0, missingAfterMove: null, still: joins ? joins.slice() : [], checked: false, after: null, missingBack: [] }
  }
  if (threw) {
    /* Every block taken out goes back where it was: the cells it was dealt into are all cells one of them came from. Each held to the preset as every write is. */
    for (const m of cleared) {
      const on = await hold()
      if (on !== 'same') {
        notBack.push(m)
        if (on === 'moved') stopped = 'moved'
        continue
      }
      try {
        await wire.placeBlock(row, m.from, m.id)
      } catch {
        notBack.push(m)
      }
    }
    log(`move: put ${cleared.map((m) => m.name).join(', ') || 'nothing'} back after`, `${threw.message}${notBack.length ? `; not put back: ${notBack.map((m) => m.name).join(', ')}` : ''}`)
    if (stopped === 'moved') return { ...counted(), joinsRefused: 0, sent: 0, missingAfterMove: null, still: joins ? joins.slice() : [], checked: false, after: null, missingBack: [] }
  }

  const settled = async () => {
    if (!measuring) return
    const now = await measure(moves, wire)
    for (const m of moves) {
      if (!now.has(m.id)) continue
      const before = was.get(m.id)
      const then = now.get(m.id)
      log(`move: ${m.name} after: ${then}${before === undefined ? '' : before === then ? ' (the same)' : ` (was ${before})`}`)
    }
  }
  /* What a failure left out of its own cell: by the read where there is one, else the put-backs that did not go. */
  const notHome = (cells) => (threw ? cleared.filter((m) => (cells ? cellAt(cells, row, m.from)?.effectId !== m.id : notBack.includes(m))).map((m) => m.name) : [])
  if (!joins) {
    await settled()
    return { ...counted(), joinsRefused: 0, sent: 0, missingAfterMove: null, still: [], checked: true, after: null, missingBack: notHome(null) }
  }

  /* THE ROW AS THE UNIT HAS IT BEFORE ANYTHING IS REPAIRED: "fed from row 3" here is a unit that keeps a join through a clear, "fed from nothing" one that drops it. */
  const straight = await readCells(wire)
  log(`move: row ${rowLabel(row)} straight after ${threw ? 'putting the blocks back' : 'the move'}: ${line(straight)}`)
  let sent = 0
  let refused = 0
  let missingAfterMove = null
  if (straight) {
    const r = await sendMissing(joins, straight, wire, log, hold)
    missingAfterMove = r.absent.length
    sent = r.sent
    refused = r.refused
    if (r.stopped) stopped = stopped || r.stopped
    log(
      'move: joins',
      r.absent.length
        ? `${r.absent.length} not there after the move (${r.absent.map(joinSaid).join('; ')}); sent ${r.sent}${r.skipped.length ? `, ${r.skipped.length} not sent: a cell is empty` : ''}${r.refused ? `, ${r.refused} answered “refused”` : ''}${r.failed ? `, stopped: ${r.failed}` : ''}${r.stopped ? `, stopped: ${r.stopped === 'moved' ? 'the unit is on another preset' : 'the unit didn’t say which preset it’s on'}` : ''}`
        : `all ${joins.length} still there after the move, none sent`
    )
  } else {
    log('move: joins', 'not checked: the grid could not be read after the move, so none was sent')
  }
  if (stopped === 'moved') return { ...counted(), joinsRefused: refused, sent, missingAfterMove, still: joins.slice(), checked: false, after: null, missingBack: [] }
  const after = straight && sent ? await readCells(wire) : straight
  if (straight && sent) log(`move: row ${rowLabel(row)} after joining it again: ${line(after)}`)
  const still = after ? missingJoins(after, joins) : joins.slice()
  if (after && still.length) log('move: still not joined', still.map(joinSaid).join('; '))
  const missingBack = notHome(after)
  if (missingBack.length) log('move: not back in their own cells', missingBack.join(', '))
  /* Where the row's Input and Output are on that read: an empty cell between them stops the sound, one outside them does not. */
  const ends = after ? rowEnds(after, row, slugsOf(blocks)) : null
  const notPlaced =
    !threw && after
      ? moves
          .filter((m) => !cellAt(after, row, m.to))
          .map((m) => ({ name: m.name, col: m.to, between: !!ends && m.to > ends.input && m.to < ends.output, gone: !after.some((c) => c && !c.isShunt && c.effectId === m.id) }))
      : []
  if (notPlaced.length) log('move: not in their new cells', notPlaced.map((x) => `${x.name} (column ${colLabel(x.col)} empty)`).join(', '))
  await settled()
  return { ...counted(), joinsRefused: refused, sent, missingAfterMove, still, checked: !!after, after, missingBack, notPlaced }
}

/**
 * A DRAG, WHOLE: what both chain editors call. Where the unit's joins are the
 * app's to make (`cables`, lib cablesLaid) the grid is read and the move
 * planned first; a plan that is refused answers { notSent: true, why } and
 * NOTHING IS SENT. Then the unit is asked which preset it is on (`onPreset`,
 * presetHold), and on another, or not saying, nothing is sent either. Then
 * the move is run, every write of it held to that preset, and `starting()`
 * is called once, just before its first write (the screens mark the chain
 * as being written there, and drop the Undo of the last change). Where his
 * settings are measured first, the unit is asked again before that first
 * write; on another preset then, or not saying, nothing is sent and the
 * answer is the same as a refusal before anything: { notSent: true, why:
 * PRESET_MOVED_BEFORE or UNIT_QUIET_BEFORE, stopped }, never a move that
 * failed part-way.
 *
 * Answers { notSent: true, why, stopped? } or { notSent: false, plan,
 * ...runMove's answer, cutsAfter } (whose `refused` counts the writes the
 * unit answered "refused"; `cutsAfter` is rowCuts on the last read, for the
 * move's row, empty spaces counted, `blocks` the chain read for the Inputs'
 * and Outputs' slugs).
 */
export async function moveBlocks({ row, moves, wire, rows = 4, cols = 12, cables = true, law = false, version = null, log = () => {}, names = null, measure = false, onPreset = null, starting = () => {}, blocks = null } = {}) {
  let plan = plainMove(row)
  if (cables) {
    const before = await readCells(wire)
    plan = planMove({ cells: before, row, moves, rows, cols, law, version })
    if (!plan.ok) {
      log(`move on row ${rowLabel(row)}`, `not sent: ${plan.why || 'nothing to move'}`)
      return { notSent: true, why: plan.why, plan }
    }
  }
  const hold = presetHold(onPreset)
  const on = await hold()
  if (on !== 'same') {
    const why = on === 'moved' ? PRESET_MOVED_BEFORE : UNIT_QUIET_BEFORE
    log(`move on row ${rowLabel(row)}`, `not sent: ${why}`)
    return { notSent: true, why, plan, stopped: on }
  }
  const res = await runMove({ plan, moves, wire, log, names, measure, hold, checkedFirst: true, starting, blocks })
  /* Held back at the first clear, after his settings were read: nothing was sent, so it is answered as a move refused before anything, in the same words. */
  if (res.heldBefore) return { notSent: true, why: res.heldBefore === 'moved' ? PRESET_MOVED_BEFORE : UNIT_QUIET_BEFORE, plan, stopped: res.heldBefore }
  /* The row asked on the move's last read as a cut row is asked: a cut the plan's own joins do not cover is said under it too. */
  const cutsAfter = res.checked && Array.isArray(res.after) ? rowCuts({ cells: res.after, blocks: blocks || [], rows, law, version, holes: true, only: [row] }) : []
  if (cutsAfter.length) log(`move: row ${rowLabel(row)} asked again`, cutsAfter[0].text)
  return { ...res, notSent: false, plan, cutsAfter }
}

/**
 * "JOIN THE ROW": read the grid, send the joins it does not show, read
 * again, and ask the row again (rowCuts on that read, with `blocks`, `rows`,
 * `law` and `version` as the cut was found by, and ALWAYS with empty spaces
 * counted, so "joined again" is never said over an empty cell between the
 * row's Input and Output, however the cut was found). `joins` are the move's
 * (after a move left one missing) or a cut row's (`rowCuts`). Every join is
 * held to the unit's preset (`onPreset`). Answers joinedWords' input: { row,
 * readBefore, sent, failed, stopped, skipped, still, checked, after, cuts },
 * and logs the row before and after.
 */
export async function joinRow({ row, joins, wire, log = () => {}, names = null, blocks = null, rows = 4, law = false, version = null, onPreset = null }) {
  const list = (joins || []).filter((j) => j && Number.isInteger(j.srcRow) && Number.isInteger(j.srcCol) && Number.isInteger(j.destRow))
  const cols = list.flatMap((j) => [j.srcCol, j.srcCol + 1])
  const first = cols.length ? Math.min(...cols) : 0
  const last = cols.length ? Math.max(...cols) : 0
  const before = await readCells(wire)
  log(`join the row: row ${rowLabel(row)} before: ${rowSaid(before, row, first, last, names)}`)
  if (!before) return { row, readBefore: false, sent: 0, failed: null, stopped: null, skipped: [], still: list, checked: false, after: null, cuts: null }
  const r = await sendMissing(list, before, wire, log, presetHold(onPreset))
  log(
    'join the row: joins',
    r.absent.length
      ? `sent ${r.sent} of ${r.absent.length} (${r.absent.map(joinSaid).join('; ')})${r.skipped.length ? `, ${r.skipped.length} not sent: a cell is empty` : ''}${r.refused ? `, ${r.refused} answered “refused”` : ''}${r.failed ? `, stopped: ${r.failed}` : ''}${r.stopped ? `, stopped: ${r.stopped === 'moved' ? 'the unit is on another preset' : 'the unit didn’t say which preset it’s on'}` : ''}`
      : 'every one already there, none sent'
  )
  if (r.stopped === 'moved') return { row, readBefore: true, sent: r.sent, failed: r.failed, stopped: r.stopped, skipped: r.skipped, still: list, checked: false, after: null, cuts: null }
  const after = r.sent ? await readCells(wire) : before
  log(`join the row: row ${rowLabel(row)} after: ${rowSaid(after, row, first, last, names)}`)
  const cuts = after ? rowCuts({ cells: after, blocks: blocks || [], rows, law, version, holes: true, only: [row] }) : null
  if (cuts?.length) log(`join the row: row ${rowLabel(row)} asked again`, cuts[0].text)
  return { row, readBefore: true, sent: r.sent, failed: r.failed, stopped: r.stopped, skipped: r.skipped, still: after ? missingJoins(after, list) : list, checked: !!after, after, cuts }
}

/* ---------------------------------------------------------------- */
/* A row that is already cut                                         */
/* ---------------------------------------------------------------- */

/**
 * Whether the chain read alone could show a cut row: a block fed from
 * nothing on the row of an Input, past it. Cheap, so the grid is read only
 * where it might be (the chain read carries no shunts, so it cannot settle
 * it either way).
 */
export function maybeCut(blocks) {
  const list = Array.isArray(blocks) ? blocks : []
  for (const input of list.filter((b) => b?.slug === 'input' && Number.isInteger(b.row))) {
    const output = list.filter((b) => b?.slug === 'output' && b.row === input.row && b.col > input.col).sort((a, b) => a.col - b.col)[0]
    if (!output) continue
    const cut = list.some((b) => b && b.row === input.row && b.col > input.col && b.col <= output.col && Array.isArray(b.fromRows) && b.fromRows.length === 0)
    if (cut) return true
  }
  return false
}

/**
 * EVERY ROW THAT READS CUT, and what would join it.
 *
 * A row with an Input and, after it on the same row, an Output, whose cells
 * between them are fed from that row or from nothing: a block (or a bare
 * wire) fed from NOTHING there is where the row stops. Each such cell is
 * joined from the cell before it on the same row, where that cell holds a
 * block, a bare wire or the Input. A row any of whose cells there is fed
 * from ANOTHER row is a parallel path and is left alone, as is one whose
 * feeds the read did not say.
 *
 * `holes` also counts an empty cell between the Input and the Output (a block
 * moved out of it): said, never joined, since nobody knows whether a join
 * into an empty cell carries the sound. `only` keeps the rows asked about.
 *
 * Join the row is offered only where the app can join EVERY cell that reads
 * cut. One it cannot (out of the top row's even columns, a join an older
 * computer app would send to the wrong cell, or a cell with an empty one
 * before it, where nothing can be joined from) is `blocked`, said with its
 * reason in the words, and the row gets no button: joining half of it
 * leaves it as silent as before, and "joined again" over that was the first
 * cut of this the review found. With `holes`, a cell fed from nothing after
 * an empty space is said with the space and is neither joined nor blocked,
 * so the button is offered for the cut cells the app can join, and the space
 * is still said after them (joinRow's answer counts it).
 *
 * Answers [{ row, col, joins, blocked, hole, holes, text }]: `col` the first
 * cut column, `joins` what Join the row sends (none while anything is
 * blocked), `blocked` the joins it cannot make (with why), `holes` whether
 * empty spaces were counted, `text` the words for it.
 */
export function rowCuts({ cells, blocks = [], rows = 4, law = false, version = null, holes = false, only = null } = {}) {
  if (!Array.isArray(cells)) return []
  const slugs = slugsOf(blocks)
  const rowsHere = [...new Set(cells.filter((c) => c && Number.isInteger(c.row)).map((c) => c.row))].sort((a, b) => a - b)
  const out = []
  for (const r of rowsHere) {
    if (Array.isArray(only) && !only.includes(r)) continue
    const ends = rowEnds(cells, r, slugs)
    if (!ends) continue
    const input = { col: ends.input }
    const output = { col: ends.output }
    const span = ends.onRow.filter((c) => c.col > input.col && c.col <= output.col)
    if (span.some((c) => feeds(c) === null)) continue
    if (span.some((c) => feeds(c).some((x) => x !== r))) continue
    const joins = []
    const blocked = []
    let first = null
    let hole = null
    for (let col = input.col + 1; col <= output.col; col++) {
      const cell = cellAt(cells, r, col)
      if (!cell) {
        if (holes && hole === null) hole = col
        continue
      }
      if (feeds(cell).length) continue
      if (first === null) first = col
      const j = { srcRow: r, srcCol: col - 1, destRow: r }
      /* Nothing before it to join it from: said, unless the empty space is said already. */
      if (!cellAt(cells, r, col - 1)) {
        if (!holes) blocked.push({ ...j, why: emptyBeforeWords(col) })
        continue
      }
      const why = joinWhyNot(j, { rows, law, version })
      if (why) blocked.push({ ...j, why })
      else joins.push(j)
    }
    if (first === null && hole === null) continue
    /* Said where the sound first stops: a cell fed from nothing, or an empty space, whichever comes first along the row. */
    const cutFirst = first !== null && (hole === null || first < hole)
    const cutText = first === null ? '' : `${cutRowWords(r, first)}${blocked.length ? ` ${blocked[0].why}` : ''}`
    const text = cutFirst ? cutText : `${holeWords(r, hole)}${cutText ? ` ${cutText}` : ''}`
    out.push({ row: r, col: cutFirst ? first : hole, joins: blocked.length ? [] : joins, blocked, hole, holes, text })
  }
  return out
}
